// spec: .qa/e2e/specs/journey.md
// seed: tests/seed.user1.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow } from '../_helpers/milestone';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

test.describe('«המסע שלי»', () => {
  test('JR-05 Ошибка загрузки קבלה — сообщение и «נסו שוב» #31c88137 @prod-safe', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    test.setTimeout(120_000);

    // 1. До перехода: пока fail = true, GET personal_commitments → abort; иначе continue.
    let fail = true;
    await page.route('**/rest/v1/personal_commitments**', async (route) => {
      if (route.request().method() === 'GET' && fail) {
        await route.abort();
      } else {
        await route.continue();
      }
    });

    // 2. Открыть `/journey`; дождаться сообщения об ошибке (до 45 с); раскрыть «מקבל על עצמי», если раскрывается.
    await page.goto('/journey');
    const errorMsg = page.getByText('הקבלה האישית לא נטענה. נסו שוב בעוד רגע.');
    await expect(errorMsg).toBeVisible({ timeout: 45_000 });

    // Порядок по кейсу JR-05 шаг 3 / плану 14.8: сначала раскрыть «מקבל על עצמי», затем искать «נסו שוב»
    // (кнопка повтора — внутри раскрытой карточки).
    const card = page.getByRole('button', { name: /^מקבל על עצמי/ });
    if (await card.count()) {
      await card.first().click();
    }
    const retry = page.getByRole('button', { name: 'נסו שוב' });
    await expect(retry.first()).toBeVisible();
    // Пустое поле «מקבל על עצמי» не показывается (ложное пустое значение недопустимо)
    const field = page.getByRole('textbox', { name: 'מקבל על עצמי' });
    if (await field.count()) {
      await expect(field).not.toHaveValue('');
    }

    // 3. fail = false → нажать «נסו שוב».
    fail = false;
    await retry.first().click();
    await expect(errorMsg).toHaveCount(0, { timeout: 30_000 });
    // Показывается «test»: в поле (карточка раскрыта на шаге 2) или в свёрнутой карточке.
    // Поле проверяется первым: у раскрытой карточки заголовок-кнопка остаётся, а «test» — в значении поля.
    const savedField = page.getByRole('textbox', { name: 'מקבל על עצמי' });
    const savedCard = page.getByRole('button', { name: /^מקבל על עצמי/ });
    await expect
      .poll(
        async () => {
          if (await savedField.count()) return `field:${await savedField.first().inputValue()}`;
          if (await savedCard.count()) return `card:${await savedCard.first().innerText()}`;
          return '';
        },
        { timeout: 30_000 },
      )
      .toMatch(/^(field:test|card:[\s\S]*test[\s\S]*)$/);
  });
});
